import type { Metadata } from "next";
import Image from "next/image";
import Link from "next/link";
import { Suspense } from "react";
import { getCartItems } from "@/lib/cart";
import { priceCart } from "@/lib/pricing";
import { formatINR } from "@/lib/money";
import { SHIPPING } from "@/lib/site";
import { ShoppingBag } from "lucide-react";
import { CartQty } from "@/components/store/CartLine";
import { RecentlyViewed } from "@/components/store/RecentlyViewed";

export const metadata: Metadata = { title: "Shopping Cart", robots: { index: false } };

async function CartContent() {
  const items = await getCartItems();
  const active = items.filter((i) => i.product.isActive);
  const quote = await priceCart(active.map((i) => ({ productId: i.productId, quantity: i.quantity, engravingText: i.engravingText })));
  const count = active.reduce((s, i) => s + i.quantity, 0);

  if (!items.length) {
    return (
      <div className="animate-scale-in card flex flex-col items-center p-10 text-center">
        <ShoppingBag className="animate-float h-12 w-12 text-brass" aria-hidden />
        <h1 className="mt-3 font-display text-2xl font-semibold">Your cart is empty</h1>
        <p className="mt-2 text-sm text-muted">Explore brass vessels, cookware, appliances and more.</p>
        <Link href="/search" className="btn-primary press mt-5">Continue shopping</Link>
      </div>
    );
  }

  return (
    <div className="grid gap-6 lg:grid-cols-[1fr_320px]">
      <div className="card p-4 sm:p-6">
        <h1 className="border-b border-line pb-3 font-display text-2xl font-semibold">Shopping Cart</h1>
        <ul className="divide-y divide-line">
          {items.map((i, idx) => {
            const p = i.product;
            const outOfStock = !p.isActive || p.stock < 1;
            return (
              <li key={i.id} className="animate-fade-up flex gap-4 py-4" style={{ animationDelay: `${idx * 60}ms` }}>
                <Link href={`/product/${p.slug}`} className="relative h-28 w-28 shrink-0 rounded-md bg-paper">
                  {p.images[0] && <Image src={p.images[0].url} alt={p.name} fill sizes="112px" className="object-contain p-2" />}
                </Link>
                <div className="flex-1 space-y-1">
                  <Link href={`/product/${p.slug}`} className="font-medium hover:text-maroon">{p.name}</Link>
                  {outOfStock ? <p className="text-sm font-semibold text-danger">Currently unavailable — please remove</p> : p.stock < i.quantity ? <p className="text-sm text-warn">Only {p.stock} available</p> : <p className="text-sm text-success">In stock</p>}
                  {i.engravingText && <p className="text-sm text-brass">Engraving: “{i.engravingText}”</p>}
                  <CartQty itemId={i.id} quantity={i.quantity} max={p.stock || i.quantity} />
                </div>
                <p className="font-semibold">{formatINR(p.price * i.quantity)}</p>
              </li>
            );
          })}
        </ul>
      </div>
      <aside className="animate-fade-up card h-fit space-y-3 p-5 [animation-delay:120ms] lg:sticky lg:top-36">
        {quote.shippingFee > 0 ? (
          <p className="text-sm text-ink-soft">Add {formatINR(SHIPPING.freeAbove - quote.subtotal)} more for <span className="font-semibold text-success">FREE delivery</span>.</p>
        ) : (
          <p className="text-sm font-semibold text-success">✓ Your order qualifies for FREE delivery.</p>
        )}
        <p className="text-lg">Subtotal ({count} items): <span className="font-semibold">{formatINR(quote.subtotal)}</span></p>
        <div className="h-1.5 overflow-hidden rounded-full bg-line"><div className="h-full origin-left animate-[grow-x_900ms_var(--ease-out)_both] rounded-full bg-success" style={{ width: `${Math.min(100, (quote.subtotal / SHIPPING.freeAbove) * 100)}%` }} /></div>
        <Link href="/checkout" className="btn-brass press w-full rounded-full py-3">Proceed to Buy</Link>
        {quote.emiEligible && quote.total >= 300000 && <p className="text-center text-xs text-muted">EMI available at checkout</p>}
      </aside>
    </div>
  );
}

export default function CartPage() {
  return (
    <div className="container-x py-6">
      <Suspense fallback={<div className="h-96 skeleton rounded-xl" />}>
        <CartContent />
      </Suspense>
      <RecentlyViewed />
    </div>
  );
}
